from pathlib import Path
from datetime import datetime,timezone
import contextlib,io,json,hashlib,sys
import numpy as np,torch,yaml
torch.set_num_threads(1);torch.set_num_interop_threads(1)
repo=Path("/home/server/liufengrong/robot_lab")
out=repo/"learnings/policy_tuning/RobotLab-Isaac-Velocity-Flat-LW-wheel-Roa-v0/2026-09-23_17-23-24/evidence/analysis/static-rightturn-policy-comparison-20260926-001"
metrics_path=out/"metrics.json";metrics=json.loads(metrics_path.read_text())
verification_path=out/"autograd-verification.json";assert not verification_path.exists()
def sha(path):return hashlib.sha256(Path(path).read_bytes()).hexdigest()
def ref(path):return {"path":str(path),"sha256":sha(path)}
for key,val in metrics["artifacts"].items():assert sha(val["path"])==val["sha256"]
samples=np.load(metrics["artifacts"]["samples_npz"]["path"],allow_pickle=False)
H10=samples["canonical_history10"];output_rows=samples["output_rows"]
sys.path.insert(0,str(repo/"rsl_rl"))
from rsl_rl.modules.actor_critic_roa import ActorCriticROA
from rsl_rl.modules.actor_critic_dwaq import ActorCriticDwaq
results={};arrays={};vectors=0
for label,binding in metrics["models"].items():
 ck=Path(binding["checkpoint"]["path"]);assert sha(ck)==binding["checkpoint"]["sha256"]
 cfg=yaml.load((ck.parent/"params/agent.yaml").read_text(),Loader=yaml.BaseLoader)["policy"]
 state=torch.load(ck,map_location="cpu",weights_only=False)["model_state_dict"]
 n=binding["history_frames"];roa=binding["algorithm"]=="ROA";velocity_on=binding["velocity_code_enabled"]
 obs={"policy":torch.zeros(1,n,39),"critic":torch.zeros(1,state["critic.0.weight"].shape[1])};groups={"policy":["policy"],"critic":["critic"]}
 kw={"actor_hidden_dims":[int(x) for x in cfg["actor_hidden_dims"]],"critic_hidden_dims":[int(x) for x in cfg["critic_hidden_dims"]],"activation":cfg["activation"]}
 with contextlib.redirect_stdout(io.StringIO()):
  if roa:
   obs["privileged"]=torch.zeros(1,state["priv_encoder.0.weight"].shape[1]);groups["privileged"]=["privileged"]
   model=ActorCriticROA(obs,groups,10,priv_encoder_dims=[int(x) for x in cfg["priv_encoder_dims"]],vel_offset=int(cfg["vel_offset"]),use_velocity_estimation=velocity_on,**kw)
  else:model=ActorCriticDwaq(obs,groups,10,vae_hidden_dims=[int(x) for x in cfg["vae_hidden_dims"]],latent_dim=int(cfg["latent_dim"]),velocity_dim=int(cfg["velocity_dim"]),**kw)
  model.load_state_dict(state,strict=True)
 model.eval();rng=torch.get_rng_state().clone()
 def graph(h,detach_codes=False):
  if roa:latent,vel=model.history_encoder(h.flatten(1))
  else:
   feat=model.encoder_backbone(h.flatten(1));latent=model.encode_mean_latent(feat);vel=model.encode_mean_vel(feat)
  if detach_codes:latent=latent.detach();vel=vel.detach()
  cur=h[:,-1]
  inp=torch.cat([cur,vel,latent],dim=-1) if roa and velocity_on else (torch.cat([cur,latent],dim=-1) if roa else torch.cat([vel,latent,cur],dim=-1))
  return model.actor(inp if roa else model.actor_obs_normalizer(inp))
 mode_j={}
 forward_errors={}
 for detach in [False,True]:
  h=torch.from_numpy(H10[:,-n:].copy()).requires_grad_(True)
  yy=graph(h,detach)
  forward_errors["actor_direct" if detach else "full"]=float(np.max(np.abs(yy.detach().numpy()-samples[label+".baseline.raw_actions"])))
  assert forward_errors["actor_direct" if detach else "full"]<1e-6
  vectors+=len(h)
  grad=[]
  for j in [0,1]:grad.append(torch.autograd.grad(yy[:,j].sum()*.25,h,retain_graph=j==0)[0].detach().numpy())
  G=np.stack(grad,axis=2)
  for kind,cols,inscale in [("q",[9,10],1.),("dq",[19,20],.05)]:
   if detach:mode_j["actor_direct_"+kind]=G[:,-1,:,cols].transpose(1,2,0)*inscale if False else G[:,-1,:,:][:,:,cols]*inscale
   else:
    mode_j["full_current_"+kind]=G[:,-1,:,:][:,:,cols]*inscale
    mode_j["history_only_coherent_bias_"+kind]=G[:,:-1,:,:][:,:,:,cols].sum(axis=1)*inscale
    mode_j["all_history_coherent_bias_"+kind]=G[:,:,:,:][:,:,:,cols].sum(axis=1)*inscale
 comparison={}
 for key,J in mode_j.items():
  assert J.shape==(505,2,2)
  arrays[label+"."+key+".autograd"]=J
  comparison[key]={}
  for stage in ["pre_turn","onset_left","growth","all_turn"]:
   bounds=binding["windows"][stage]["row_index_inclusive"];mask=(output_rows>=bounds[0])&(output_rows<=bounds[1])
   exact=np.linalg.svd(J[mask].astype(np.float64),compute_uv=False)[:,0]
   entry={"autograd_gain_median":float(np.median(exact)),"autograd_gain_max":float(exact.max())}
   for eps in [1,2]:
    fd=samples[label+"."+key+".eps"+str(eps)]
    f_gain=np.linalg.svd(fd[mask],compute_uv=False)[:,0]
    abs_error=np.linalg.norm((fd-J)[mask],axis=(1,2))
    relative=abs_error/np.maximum(np.linalg.norm(J[mask],axis=(1,2)),1e-12)
    entry["finite_difference_eps"+str(eps)]={"gain_median":float(np.median(f_gain)),"gain_median_relative_error":float(abs(np.median(f_gain)-np.median(exact))/max(np.median(exact),1e-12)),"matrix_absolute_error_median":float(np.median(abs_error)),"matrix_absolute_error_max":float(abs_error.max()),"matrix_relative_error_median":float(np.median(relative)),"matrix_relative_error_max":float(relative.max())}
   comparison[key][stage]=entry
 results[label]={"forward_max_abs_raw_action_errors":forward_errors,"jacobian_checks":comparison,"input_vectors":1010}
 assert torch.equal(rng,torch.get_rng_state())
 assert all(param.grad is None for param in model.parameters())
 print("AUTOGRAD",label,{"onset_q":comparison["full_current_q"]["onset_left"]["autograd_gain_median"],"growth_q":comparison["full_current_q"]["growth"]["autograd_gain_median"],"onset_dq":comparison["full_current_dq"]["onset_left"]["autograd_gain_median"],"growth_dq":comparison["full_current_dq"]["growth"]["autograd_gain_median"]},flush=True)
assert metrics["method"]["finite_budget"]["actual_model_input_vectors"]+vectors<=400000
assert all(results[label]["jacobian_checks"][kind][stage]["finite_difference_eps1"]["gain_median_relative_error"]<.01 for label in results for kind in ["full_current_q","full_current_dq"] for stage in ["pre_turn","onset_left","growth","all_turn"])
npz_path=out/"autograd-jacobians.npz";assert not npz_path.exists();np.savez_compressed(npz_path,**arrays)
verification={"schema_version":1,"created_at":datetime.now(timezone.utc).isoformat(),"analysis":"Independent reverse-mode autodiff verification of finite-difference hip target sensitivities","parent_metrics":ref(metrics_path),"parent_samples":metrics["artifacts"]["samples_npz"],"results":results,
 "validation":{"all_primary_current_frame_gain_medians_match_autograd_within_1_percent":True,"all_autograd_forward_outputs_match_saved_Native_actions_within_1e_6":True,"weight_gradient_buffers_not_populated":True,"inference_rng_unchanged_after_model_loading":True},
 "weak_derivative_qualification":"Old DWAQ historical-only derivatives are very small; their relative finite-difference error can be large due to float32 cancellation. Use autograd for that weak pathway. Core current-frame comparisons passed the independent check.",
 "finite_budget":{"additional_model_input_vectors":vectors,"combined_total_model_input_vectors":metrics["method"]["finite_budget"]["actual_model_input_vectors"]+vectors,"approved_scope":"Same 8 models and same 505 frozen rows; derivative validation only"},
 "artifacts":{"jacobians":ref(npz_path)},"source":{"python":ANALYSIS_SOURCE,"sha256":hashlib.sha256(ANALYSIS_SOURCE.encode()).hexdigest()}}
with verification_path.open("x") as f:json.dump(verification,f,indent=2,ensure_ascii=False,allow_nan=False);f.write("\n")
print("AUTOGRAD_COMPLETED",json.dumps(ref(verification_path)),flush=True)
